using System;using System.IO;using System.Linq;using System.Text;using UnityEngine;using UnityEngine.SceneManagement;using UnityEditor;
[InitializeOnLoad]public static class CityRoadWaterCheck{static CityRoadWaterCheck(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists("CityRoadWaterCheck.request"))return;File.Delete("CityRoadWaterCheck.request");try{var scene=SceneManager.GetActiveScene();var b=new StringBuilder();foreach(var m in scene.GetRootGameObjects().SelectMany(x=>x.GetComponentsInChildren<Renderer>(true)).SelectMany(x=>x.sharedMaterials).Where(x=>x).Distinct().Where(x=>x.name.ToLower().Contains("road")||x.name.ToLower().Contains("water")||x.shader.name.ToLower().Contains("road"))){b.AppendLine("MAT "+AssetDatabase.GetAssetPath(m)+" SHADER "+m.shader.name+" keywords="+string.Join(",",m.shaderKeywords));b.AppendLine("SHADER_ERRORS="+ShaderUtil.GetShaderMessages(m.shader).Count(x=>x.severity.ToString()=="Error"));foreach(var p in m.GetTexturePropertyNames())b.AppendLine(p+"="+AssetDatabase.GetAssetPath(m.GetTexture(p)));foreach(var p in new[]{"_Metallic","_Smoothness","_Road0Smoothness","_Road1Smoothness","_Road2Smoothness","_Road3Smoothness","_Road4Smoothness"})if(m.HasProperty(p))b.AppendLine(p+"="+m.GetFloat(p));}if(SceneView.lastActiveSceneView){var c=SceneView.lastActiveSceneView.camera;b.AppendLine("VIEW "+c.transform.position+" ROT "+c.transform.eulerAngles);}var view=SceneView.lastActiveSceneView; if(view){var capture=typeof(FinalPNGCityDetails).GetMethod("Capture",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic);capture.Invoke(null,new object[]{scene,new Vector3(292.90f,48.85f,56.57f),new Vector3(292.90f,48.85f,56.57f)+Quaternion.Euler(25.20f,274.45f,0)*Vector3.forward*80,File.Exists("CityRoadWaterAfter.request")?"RoadWater-After":"RoadWater-Before"});}if(File.Exists("CityRoadWaterAfter.request")){var capture=typeof(FinalPNGCityDetails).GetMethod("Capture",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic);var p=new Vector3(292.90f,48.85f,56.57f);var dir=Quaternion.Euler(25.2f,274.45f,0)*Vector3.forward;capture.Invoke(null,new object[]{scene,p+dir*30,p+dir*80,"RoadWater-Close"});} File.WriteAllText("FinalEnvironmentRoadReview/RoadWaterAudit.txt",b.ToString());}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/RoadWaterAudit.txt",e.ToString());}}}



